\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 68va-70va}}\plain \f1\b\lang1033\fs22  (= Schum 67va-69va) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \u8218 \'82De anatomia humani corporis\lquote }}\plain \f1\b\lang1033\fs22  (Nachtrag)
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 (68va) \u252 \'fcber dem Schriftraum: >\plain \f1\i\lang1033\fs22 De anathomia humani corporis\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 . \plain \f1\lang1033\fs22 Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Constituentia corpus humanum sunt humores, spiritus et membra}}\plain \f1\i\lang1033\fs22  ... \endash  ... \plain \f1\lang1033\fs22 (70va) \plain \f1\i\lang1033\fs22 et ex coriatione intestinorum appellatur dissinteria ab incisione intestinorum.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Thorndike/Kibre 258.5}}\plain \f1\lang1033\fs22\cf1  (nur diese Hs.). \endash  Sonst nicht nachweisbar, vermutlich Auszug aus einem umfassenderen Werk. Es handelt sich nicht um Teil 3 (\u8218 \'82Anathomia\lquote ) des \u8218 \'82Micrologus\lquote  des Richardus Anglicus, der \u252 \'fcblicherweise das Incipit \u8222 \'84Galienus testatur\ldblquote  oder \u8222 \'84Galieno testante in Tegni\ldblquote  hat (Ed. Sudhoff, Der \u8222 \'84Micrologus"-Text der \u8222 \'84Anatomia" Richards des Engl\u228 \'e4nders [1927]), aber wohl in einzelnen Textzeugen auch mit \u8222 \'84Constituencia corporis humani tria sunt\ldblquote  beginnt, vgl. etwa Thomson, Descriptive catalogue Merton College Oxford (2009), S. 248-249, zu Oxford, Merton College, Ms 324, Bl. 151v-153r (dieses Incipit auch in Oxford, Bodleian Library, E musaeo 219, Bl. 145-147r, Titel \u8218 \'82Liber anathomiae\lquote ; vgl. Thorndike/Kibre 258.4). }

