\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f2\lang1033\fs22 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 73r-84ra}}\plain \f1\b\lang1033\fs22  (= Schum 72ra-83ra) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Isaac Israelita}}\plain \f1\b\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \u8218 \'82De elementis\lquote }}\plain \f1\b\lang1033\fs22  in der \u220 \'dcbersetzung des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Gerardus Cremonensis}}
