\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 161rc-161vc}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Verzeichnis von Heilmitteln, insb. Purgantien}}\plain \f1\lang1033\fs22 . Erster Eintrag: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Hec purgant fleuma dulce}}\plain \f1\i\lang1033\fs22 : bruscus, sparagus, sinonum, anisum, feniculum, anetum, ameos, polipodium, macedonus, apium, coriandrum. \plain \f1\lang1033\fs22 Dieser Eintrag stimmt weitgehend mit dem Kapitel 125 \u8222 \'84Purgantia fleuma dulce\ldblquote  des Compendium Salerni \u252 \'fcberein, vgl. Renzi (Hg.), Collectio Salernitana V (1859), S. 231, hier auch weitere der folgenden Eintragungen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Ebrima;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Geschichte: \plain \f1\lang1033\fs22 Der Faszikel\plain \f1\b\lang1033\fs22  \plain \f1\lang1033\fs22 ist nach Schrift und Buchschmuck im {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 4. Viertel des 13. Jhs.}}\plain \f1\lang1033\fs22  in {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Nordfrankreich}}\plain \f1\lang1033\fs22  entstanden. Ausf\u252 \'fchrliche marginale und interlineare Notizen von mehreren H\u228 \'e4nden der 1. H\u228 \'e4lfte des 14. Jhs. belegen eine intensive Nutzung, bevor der Faszikel im 3. Viertel des 14. Jhs. mit den anderen Faszikeln zu dem hier \u252 \'fcberlieferten Codex zusammengestellt wurde. Die volkssprachige Interlinearglosse \plain \f1\i\lang1033\fs22 halseluuort\plain \f1\lang1033\fs22  zu \plain \f1\i\lang1033\fs22 asarum\plain \f1\lang1033\fs22  (Niederdeutsch, Niederrheinisch oder Niederl\u228 \'e4ndisch) legt nahe, dass sich der Faszikel in dieser Zeit im Raum nordwestlich von K\u246 \'f6ln befand.}

