\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Inhalt:
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 162r-177r}}\plain \f1\b\lang1033\fs22  (= Schum 160r-175r) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Nicolaus Salernitanus}}\plain \f1\b\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \u8218 \'82Antidotarium Nicolai\lquote }}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 162r \u220 \'dcber dem Schriftraum \plain \f1\i\lang1033\fs22 Antidotarius cum glosa \plain \f1\lang1033\fs22 (2. Viertel 14. Jh.). \u220 \'dcber dem Text: >\plain \f1\i\lang1033\fs22 Incipit\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 Antidotarius Nycolai\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 .
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 162r Prolog: \plain \f1\i\lang1033\fs22 >E<{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 go Nycolaus rogatus a quibusdam in practica}}\plain \f1\i\lang1033\fs22  studere uolentibus \plain \f1\lang1033\fs22 [marginal nachgetragen:] \plain \f1\i\lang1033\fs22 medicine \u8230 \'85\plain \f1\lang1033\fs22  \endash  \u8230 \'85 \plain \f1\i\lang1033\fs22 per hoc enim facilis et certa erit emptio \plain \f1\lang1033\fs22 [Druck: noticia emptionis] \plain \f1\i\lang1033\fs22 leue precium moderata dispensatio. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 162r-177r Text: \plain \f1\i\lang1033\fs22 >A<{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 vrea Alexandrina ab auro dicta est, }}\plain \f1\i\lang1033\fs22 Alexandrina quia ab Alexandro peritissimo philosopho inuenta\plain \f1\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 (177r) [Z]\plain \f1\i\lang1033\fs22 inziber conditum \u8230 \'85 \plain \f1\lang1033\fs22 [E]\plain \f1\i\lang1033\fs22 t quia sufficienter de dispensatione omnium confectionum et emplastrorum\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 atque unguentorum diximus, nunc uidendum est de speciebus et herbis secundum pondus proprium et mensuras\plain \f1\lang1033\fs22  \u8230 \'85 \plain \f1\i\lang1033\fs22 et cum dispensandi habeant copiam de \plain \f1\lang1033\fs22 (!)\plain \f1\i\lang1033\fs22  nummorum et amicorum plenitudine glorieNtuR. \plain \f1\lang1033\fs22 [hier ohne das sonst oft folgende und mit dem Antidotarium verbundene \u8218 \'82De dosis medicinarum\lquote . Der letzte Absatz des Antidotariums \plain \f1\i\lang1033\fs22 Et quia sufficienter \plain \f1\lang1033\fs22 wird teilweise auch als Prolog von \u8218 \'82De dosis medicinarum\lquote  aufgefasst, vgl. Thorndike/Kibre 1231.12]
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 Enth\u228 \'e4lt nur 95 der sonst \u252 \'fcblichen mindestens 110-115 Vorschriften, von \u8218 \'82Aurea Alexandrina\lquote  bis \u8218 \'82Zinziber conditum\lquote . Im Vergleich zur Liste bei Goltz, Antidotarium Nicolai (1976), S. 218, fehlen insbesondere die Syrupe und Trocisci sowie viele Pillule.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Thorndike/Kibre 165.6, 490.2-4 (ohne diese Hs.) sowie 1231.12}}\plain \f1\lang1033\fs22  (letzter Abschnitt behandelt als Prolog zu De dosibus medicinarum). \endash  {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Klebs 703.}}\plain \f1\lang1033\fs22  \endash  Verglichen mit dem Druck Neapel 1478 ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GW M26751}}\plain \f1\lang1033\fs22 ). \endash  Zum Werk: Goltz, Antidotarium Nicolai (1976).
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 172r-v Schaltzettel, Papier, urspr\u252 \'fcnglich wohl einliegender Notizzettel: Rezepte, von drei H\u228 \'e4nden, 172v oben \u228 \'e4ltere gotische Kursive (3. Viertel 14. Jh.), 172r oben und 172v unten j\u252 \'fcngere gotische Kursive (Wolbero de Kaldenhoven [Pfeil dagegen: \u8222 \'84m\u246 \'f6glicherweise Amplonius\ldblquote ], 4. Viertel 14. Jh.), 172r unten (kopfst\u228 \'e4ndig) j\u252 \'fcngere gotische Kursive (4. Viertel 14. Jh.). Darunter: 172r \plain \f1\i\lang1033\fs22 Sirupus raphaninus\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Sirupus de menta\plain \f1\lang1033\fs22 ;\plain \f1\i\lang1033\fs22  Sirupus de succis;\plain \f1\lang1033\fs22  172v:\plain \f1\i\lang1033\fs22  Pillule de fumo terre\plain \f1\lang1033\fs22 ;\plain \f1\i\lang1033\fs22  Pillule viole; Pillule magistri Nycolai; Pillule de aloe et mascis\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Pillule magistri Galli.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 177v leer}

