\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 19ra-183rb}}\plain \f1\b\lang1033\fs22  (= Schum 19ra-182rb) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Johannes Serapio}}\plain \f1\b\lang1033\fs22  (Senior): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \u8218 \'82Breviarium sive Practica medicinae\lquote }}\plain \f1\b\lang1033\fs22  in der \u220 \'dcbersetzung des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Gerardus Cremonensis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 19ra Prolog und Kapitelverzeichnis Traktat 1 [\u220 \'dcberschrift:] >\plain \f1\i\lang1033\fs22 Tractatus primus Breuiarii filii Serapionis medici translatus a magistro Girardo Cremonensi de arabico in latinum. Inquid Johannes\plain \f1\lang1033\fs22 <. [Initium:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >I<ncipiamus cum auxilio Dei et bonitate inspiracionis eius}}\plain \f1\lang1033\fs22  ... \plain \f1\i\lang1033\fs22 32\plain \f1\i\super\lang1033\fs24 m\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 De saltu.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 19ra-183rb Text: [\u220 \'dcberschrift Kapitel 1:] >\plain \f1\i\lang1033\fs22 Capitulum primum de caluicio et allopicia et tyria\plain \f1\lang1033\fs22 <. [Initium:] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >E<gritudines iste a duabus eueniunt causis}}\plain \f1\lang1033\fs22  ... \endash  ... (183rb) \plain \f1\i\lang1033\fs22 et conficiatur cum melle despumato et amministretur in omni quod dicitur in mugith. Completum est postremum agregati ex libro medicine Iohannis filii Serapionis. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Binnengliederung: Beginn der Traktate (jeweils mit vorangestelltem Kapitelverzeichnis): Traktat 1: 19ra; Traktat 2: 35ra; Traktat 3: 53vb; Traktat 4: 67vb; Traktat 5: 91ra; Traktat 6: 112va; Traktat 7: 121rb.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Thorndike/Kibre 723.8}}\plain \f1\lang1033\fs22  (Prolog), 493.8 (Text) (ohne diese Hs.). \endash  Klebs 911.1-2, 912.1 (entpricht {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GW M41683 [Venedig 1479], M41687 [Venedig 1497]) \endash  au\u223 \'dferdem: GW M41679-41682}}\plain \f1\lang1033\fs22  ([vor 1479], Basel 1499, Ferrara 1488, Lyon [vor 1497]). }

