\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 328ra-328va Prolog und Kapitelverzeichnis: [Rubrik rechts:] >\plain \f1\i\lang1033\fs22 Verba Albubetri filii Zacorini Arasi\plain \f1\lang1033\fs22  <. [Initium Prolog:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >D<ixi in hoc libro meo medicinas, quarum neccesitas est inseparabilis,}}\plain \f1\i\lang1033\fs22  et posui illas, que ex eis sunt preclare et electe ... >D<e algebra \plain \f1\lang1033\fs22 [Zusatz von Faszikel 1, H1:]\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 >\plain \f1\i\lang1033\fs22 60\plain \f1\lang1033\fs22 <\plain \f2\lang1033\fs22 .\plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Verba Albubetri\plain \f1\lang1033\fs22 <. >\plain \f1\i\lang1033\fs22 I\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 am\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 quidem peruenimus ad expositionem relacionis egritudinum\plain \f1\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 (328va) \plain \f1\i\lang1033\fs22 et illic inuenietur.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 328va-339vb Text: [\u220 \'dcberschrift Kapitel 1:] \plain \f1\i\lang1033\fs22 De tinctura capillorum\plain \f2\lang1033\fs22 .\plain \f1\lang1033\fs22  [Initium Text:] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >C<onfectio tincture denigrantis capillos}}\plain \f1\i\lang1033\fs22  ...\plain \f2\i\lang1033\fs24  \plain \f1\lang1033\fs22 \endash  ... (339vb) \plain \f1\i\lang1033\fs22 Sedat enim dolorem, usque quo fiat algebra. Vnguentum egyptiacum  \u8230 \'85 deinde repone ipsum. Explicit Antidotarius Rasi. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Thorndike/Kibre 445.6}}\plain \f1\lang1033\fs22  (Prolog), 245.14 (Text) (ohne diese Hs.). \endash  Klebs 826.1-3 (Rhazes, Opera: Mailand 1481, Venedig 1497, Venedig 1500; entspricht{\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17  GW M37978, M38002, M37986}}\plain \f1\lang1033\fs22 ). \endash  Verglichen mit Druck Venedig 1497 (GW 38002), Bl. 80v-86v.}

