\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 U.a.: (340ra) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >D<olor capitis inuenitur item si fuerit in tempore caloris}}\plain \f1\i\lang1033\fs22 , sumatur illud quod narro: conditi rosati ex zuccarro ... \plain \f1\lang1033\fs22 (340ra) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Stricture uero anhelitus non est causa nisi addicio carnis}}\plain \f1\i\lang1033\fs22  et dimissio exercicii et ieiunio et conseruacio illius eleuacionis \u8230 \'85 \plain \f1\lang1033\fs22 (340rb) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Emplastrum resoluens apostemata et aperiens ea}}\plain \f1\i\lang1033\fs22 . Recipe picis albe, medulle cruris uaccini \u8230 \'85 \plain \f1\lang1033\fs22 (340rb) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat19 Emplastrum ad apostemata ambulativa in membris et scrophulis et cancro}}\plain \f1\i\lang1033\fs22 . Recipe cere resine pini \plain \f1\lang1033\fs22 \u8230 \'85 (340rb) \plain \f1\i\lang1033\fs22 Vnguentum ad fistulam. Recipe litargiri auris\plain \f1\lang1033\fs22  \u8230 \'85 (340vb) \plain \f1\i\lang1033\fs22 Sirupus zuphe ad tussim\plain \f1\lang1033\fs22  \u8230 \'85 (341ra) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vnguentum ad omnes pustulas vbicumque sint in corpore}}\plain \f1\lang1033\fs22  \u8230 \'85 \plain \f1\i\lang1033\fs22 quod sufficit\plain \f2\lang1033\fs22 .
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Thorndike/Kibre 461.8}}\plain \f1\lang1033\fs22  (nur diese Hs.). \endash  Von Schum (und ihm folgend Pfeil) nach dem ersten Absatz als \u8218 \'82Tractatus de dolore capitis\lquote  bezeichnet.}

