\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >B<aurac id est omne genus salis, sal nigrum, sal napticum}}\plain \f1\lang1033\fs22  ... \endash   ... (343vb) \plain \f1\i\lang1033\fs22 Ezerehasen id est uitis albe\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Diamare id est confectio de pinguedine gibbi\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Mehezaram id est arnoglossa. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Seitentitel ab 342vc: >\plain \f1\i\lang1033\fs22 Exposiciones vocabulorum arabicorum, que sunt in Divisionibus et Anthidotarium Rasis\plain \f1\lang1033\fs22 <. Nicht alphabetisch. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Thorndike/Kibre 174.2}}\plain \f1\lang1033\fs22 . \endash  Textbeginn und die ersten Lemmata \u252 \'fcbereinstimmend mit den \u8218 \'82Expositiones Rasis\lquote  in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CA 2\u176 \'b0 265}}\plain \f1\lang1033\fs22 , Bl. 110rb-111va, dar\u252 \'fcber hinaus zahlreiche weitere \u220 \'dcbereinstimmungen, jedoch auch Abweichungen und deutlich geringerer Lemmatabestand, das letzte Lemma hier ist das f\u252 \'fcnftletzte in CA 2\u176 \'b0 265. Vgl. auch Chandelier u. a.: Manuscrits m\u233 \'e9dicaux (2006), S. 140 (f\u252 \'fcnf Textzeugen in der BNF mit diesem Incipit, hier als \u8218 \'82Expositiones Rasis, libri Almansoris et libri divisionum\lquote  bezeichnet). }

