\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 41va-45rc}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Sachindex zum Tacuinum sanitatis}}\plain \f1\lang1033\fs22  \plain \f1\b\lang1033\fs22 (\u8218 \'82Tabula bona super Tacuino\rquote , Nachtrag von NH1) 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 [A]\plain \f1\i\lang1033\fs22 bstinendum est a quibusdam cibariis ne in eadem comestione sumantur 21.a. \plain \f1\lang1033\fs22 /\plain \f1\i\lang1033\fs22  Absincium 10.f. \u8230 \'85 \endash  \u8230 \'85 \plain \f1\lang1033\fs22 (45rc)\plain \f1\i\lang1033\fs22  Zuccarum 22.b. 24.e. 25.ab. 30.a.b. \plain \f1\lang1033\fs22 / \plain \f1\i\lang1033\fs22 Zuccarum rosaceum 1.e. Explicit Tacuinus amen. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Nicht bei eTK. \endash  Nach Ventura, ebd., in der \u220 \'dcberlieferung des Tacuinum nur ein weiterer Textzeuge: Mantua, Biblioteca Civica, MS F. IV 10 (741), Bl. 1r-10r (14. Jh.). }

