\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 46va-b}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Astronomische Notizen, wohl Erg\u228 \'e4nzung zur \u8218 \'82Astrologia Ypocratis\lquote }}\plain \f1\b\lang1033\fs22  (Nachtrag von NH2)
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Unmittelbar an die \lquote {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Astrologia Ypocratis}}\plain \f1\lang1033\fs22 \rquote  anschlie\u223 \'dfend, zunehmend verblasst, teils schwer lesbar: (46va) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 [N]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ota quod quadruplex est aspectus lune in circulo suo}}\plain \f1\i\lang1033\fs22  ... \endash  ... \plain \f1\lang1033\fs22 (46vb) \plain \f1\i\lang1033\fs22 in opposito semper sunt\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 coniuncta\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 soli. \plain \f1\lang1033\fs22 Nicht identifiziert. }

