\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 112vb-112vd}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Ausgabenverzeichnis}}\plain \f1\b\lang1033\fs22  (Nachtrag, Ende 13./Anfang 14. Jh., Oberitalien)
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Ca. 100 Eintr\u228 \'e4ge, z. B.: (112vb) \plain \f1\i\lang1033\fs22 Item uxori per sac. \plain \f1\lang1033\fs22 (?; sacramentum, sacerdotem?, in Frage kommt auch die Lesung \plain \f1\i\lang1033\fs22 suc.\plain \f1\lang1033\fs22 ) ... [folgt wohl Zahlenangabe, nicht sicher lesbar] \plain \f1\i\lang1033\fs22 i turenos\plain \f1\lang1033\fs22  (?) / \plain \f1\i\lang1033\fs22 Item Bonae iii denarios\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in capella xii d.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item filianis meis pro offerta ii s[olidos]\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item pro fibula vii s.\plain \f1\lang1033\fs22  / \u8230 \'85 / \plain \f1\i\lang1033\fs22 Item Magno Passarello xl s.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item in uno pari caligarum de Bruneco\plain \f1\lang1033\fs22  ... / \plain \f1\i\lang1033\fs22 Item in natale ad lud. iii sol. \plain \f1\lang1033\fs22 /\plain \f1\i\lang1033\fs22  Item in cartis xvi d. \plain \f1\lang1033\fs22 / \u8230 \'85 / (112vc) ... \plain \f1\i\lang1033\fs22 Item archipresbitero xv s.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in calciamentis Bone v s. et iii d.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in artibus Iuppe\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 vi\plain \f1\lang1033\fs22  (?) \plain \f1\i\lang1033\fs22 d.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item in uino cum uenit Aliatic. \plain \f1\lang1033\fs22 (?) \plain \f1\i\lang1033\fs22 et bebe vi. d.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in lignis vi s.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in companatico cum fui Sarm\plain \f1\lang1033\fs22 . \plain \f1\i\lang1033\fs22 xii s\plain \f1\lang1033\fs22 . / ... / \plain \f1\i\lang1033\fs22  Item in uectura equi et asini cum re[uer]sus fui a Nag. \plain \f1\lang1033\fs22 (?)\plain \f1\i\lang1033\fs22  iii s.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in annona et palea xx d.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item in planellis et caligis iii s.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item quando uenerunt Sar[u]minicenses\plain \f1\lang1033\fs22  (?) \plain \f1\i\lang1033\fs22 in eorum expensis xx d. \plain \f1\lang1033\fs22 / [durchstrichen:] \plain \f1\i\lang1033\fs22 Item Bone pro fibula iii s. et iii d.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item pro panno tunice uxori iiii s.\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Item in lucerna domini C. xviii d.\plain \f1\lang1033\fs22  / ... \plain \f1\i\lang1033\fs22 Item in expensis festi sancti sacramenti \plain \f1\lang1033\fs22 (?) \plain \f1\i\lang1033\fs22 ii s. et iiii d. \plain \f1\lang1033\fs22 [bei dieser Aufl\u246 \'f6sung der K\u252 \'fcrzung \plain \f1\i\lang1033\fs22 s. sac.\plain \f1\lang1033\fs22  datierbar \u8222 \'84nach 1264\ldblquote  (Erhebung des Fronleichnamsfestes zum Fest der Gesamtkirche durch Papst Urban IV.)] / \plain \f1\i\lang1033\fs22 Item iudeis xxx sol. \plain \f1\lang1033\fs22 [darunter ausgestrichen: \plain \f1\i\lang1033\fs22 v s. in quibus x s\plain \f1\lang1033\fs22 .] \plain \f1\i\lang1033\fs22 veneretur \plain \f1\lang1033\fs22 (?)\plain \f1\i\lang1033\fs22  eis.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item in pipere iii s.\plain \f1\lang1033\fs22  / ... (112vd) \plain \f1\i\lang1033\fs22 Item pro laqueo pellis x d. \plain \f1\lang1033\fs22 / \plain \f1\i\lang1033\fs22 Item pro boccarano xx d.\plain \f1\lang1033\fs22  / \u8230 \'85 / \plain \f1\i\lang1033\fs22 Item Sarm. iii sol. pro lopinario \plain \f1\lang1033\fs22 / \plain \f1\i\lang1033\fs22 Item pro factura anuli xii d. \plain \f1\lang1033\fs22 / ... /\plain \f1\i\lang1033\fs22  Item in bonbice xxx d. \plain \f1\lang1033\fs22 / \u8230 \'85 / \plain \f1\i\lang1033\fs22 Item in cultellis pro tabula xxx d. \plain \f1\lang1033\fs22 / \plain \f1\i\lang1033\fs22 \u8230 \'85 Item in bagina cultellorum pro tabula ii. s. \plain \f1\lang1033\fs22 /\plain \f1\i\lang1033\fs22  \u8230 \'85 Item in curatis proscribendo artem notam \plain \f1\lang1033\fs22 (?) xii d. / \u8230 \'85 / \plain \f1\i\lang1033\fs22 Item Ynno pro pelle xx sol.\plain \f1\lang1033\fs22  / ... / \plain \f1\i\lang1033\fs22 Item in electuario, quod dedi vicario xviii d.\plain \f1\lang1033\fs22  / ... /\plain \f1\i\lang1033\fs22  Item Magno Passarello xx sol. \plain \f1\lang1033\fs22 /\plain \f1\i\lang1033\fs22  Item Iac[obo] Criscentio\plain \f1\lang1033\fs22  (?)\plain \f1\i\lang1033\fs22  ii s. \plain \f1\lang1033\fs22 / ... \plain \f1\i\lang1033\fs22 Item in aliis ii uenicianos 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Personennamen: Bona, Iuppa (wohl die T\u246 \'f6chter des Schreibers), Magnus Passarelli, filia compatris Cinthii, Gregorius, Ynnus, Melaria, dominus Rogerus, Iacobus Criscentius (?). \endash  Ortsname: \plain \f1\i\lang1033\fs22 caligae de Bruneto\plain \f1\lang1033\fs22  [nach Orbis latinus: Brugnato, Ligurien, nordwestl. von La Spezia, in Frage kommt auch die Lesung \plain \f1\i\lang1033\fs22 de Bruneco\plain \f1\lang1033\fs22 , die auf Bruneck in S\u252 \'fcdtirol hinweisen k\u246 \'f6nnte], weitere mutma\u223 \'dfliche Ortsnamen (s. oben) lie\u223 \'dfen sich nicht sinnvoll verifizieren. \endash  W\u228 \'e4hrungen: \plain \f1\i\lang1033\fs22 denarii\plain \f1\lang1033\fs22 , \plain \f1\i\lang1033\fs22 solidi\plain \f1\lang1033\fs22 , \plain \f1\i\lang1033\fs22 venetiani\plain \f1\lang1033\fs22 , im ersten Eintrag wohl auch\plain \f1\i\lang1033\fs22 tureni \plain \f1\lang1033\fs22 (gemeint wohl der grossus turonus, Tournois, im Umlauf seit 1266).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Blockweise angelegt, aus inhaltlichen und pal\u228 \'e4ographischen Gr\u252 \'fcnden offensichtlich in Oberitalien von einem praktizierenden, verheirateten Arzt, der Kinder hatte und verm\u246 \'f6gend war (Aufwendungen f\u252 \'fcr feine Stoffe, u. a. Halbseide und Buckram [feines Gewebe arabischen Ursprungs; vgl. dazu Mittellateinisches W\u246 \'f6rterbuch s. v. bombyx, buccaranus], Pelz, Schmuck, Ringe, Stiefel, Pfeffer, Papier, Reisen, Pferdefutter, Bordellbesuche von G\u228 \'e4sten [\plain \f1\i\lang1033\fs22 pro lopinario\plain \f1\lang1033\fs22 , d. h. lupinario]).}

