\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 147r-148r}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Quaestiones}}\plain \f1\b\lang1033\fs22  (Zusammenfassungen; am Lagenbeginn, wohl Nachtrag)\plain \f1\lang1033\fs22 : (147r) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vtrum omnis digestio medicine fiat }}\plain \f1\i\lang1033\fs22 a calore radicali. Arguitur, quod sic \u8230 \'85\plain \f1\lang1033\fs22 ; (147r)\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vtrum primum nocumentum sit in corde}}\plain \f1\i\lang1033\fs22 , cum accidit diminucio humorum a quantitate neccessaria\plain \f1\lang1033\fs22  (nicht ausgef\u252 \'fchrt, Rest der Seite leer); (147v) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vtrum flebotomia plus debilitet cor quam farmacia}}\plain \f1\i\lang1033\fs22 . Dicitur, quod flebotomia\plain \f1\lang1033\fs22  \u8230 \'85; (147v) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Vtrum in quolibet humani corporis membro}}\plain \f1\i\lang1033\fs22  sint 4\plain \f1\i\super\lang1033\fs24 or\plain \f1\i\lang1033\fs22  virtutes naturales. Arguitur, quod non\plain \f1\lang1033\fs22  \u8230 \'85 (148r) Teil einer Qu\u228 \'e4stio, setzt ein mit \plain \f1\i\lang1033\fs22 contra notabile 2\plain \f1\i\super\lang1033\fs24 m\plain \f1\i\lang1033\fs22  circa proprias uel est prima uel 2\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs22  \u8230 \'85 . \plain \f1\lang1033\fs22 147r \u252 \'fcber dem Schriftraum Notiz \plain \f1\i\lang1033\fs22 Nota Cor sentio, pulmo loquitur, fel commouet iram, splen ridere facit cogit amare iecur.}

