\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat18 143ra-144rb}}\plain \f1\b\lang1033\fs22  Medizinische {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat18 Quaestio }}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat18 Est igitur dubitacio non modica, vtrum medicine calide et frigide possint}}\plain \f1\i\lang1033\fs22  in corpore nostro ad actum reduci, per quem calefaciant vel infrigident. Et videtur primo, quod hoc in calidis nullomodo sit possibile\plain \f1\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 (144rb) \plain \f1\i\lang1033\fs22 sequitur in consequens, vt visum est et hoc sufficit de ista questione igitur ad presens etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Nicht identifiziert. Nicht identisch mit einer der Qu\u228 \'e4stionen \u252 \'fcber den Tegni in Marsilius\lquote  Kommentar in Wolfenb\u252 \'fcttel, HAB, Guelph. 17.2 Aug. fol. (s. oben). }

