\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Collegium Portae Coeli, 59 medicinae  \u8226 \bullet   {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Pergament}}\plain \f1\b\lang1033\fs22   \u8226 \bullet   {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 I+114+I}}\plain \f1\b\lang1033\fs22   \u8226 \bullet   {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 29 x 21,5}}\plain \f1\b\lang1033\fs22  cm  \u8226 \bullet   {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 I: Italien (?), II-IV: Frankreich (?)}}\plain \f1\b\lang1033\fs22   \plain \f2\b\lang1033\fs22 \u8226 \bullet \plain \f1\b\lang1033\fs22   I-IV: {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 1. Viertel 14. Jh.}}}

