\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Inpuritas seu turbatio vel obscuritas debet esse in vrina febricitantis}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f2\i\lang1033\fs24  \endash  \u8230 \'85 \plain \f1\lang1033\fs22 (82vb)\plain \f1\i\lang1033\fs22  ut spuma fiat precipue cum veniens ad secundam \plain \f1\lang1033\fs22 (?)\plain \f1\i\lang1033\fs22  digestionem ventositas elimat quare \plain \f1\lang1033\fs22 [bricht ab; vermutlich Lagenverlust]
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 Nicht identifiziert.}

