\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 117vb-118ra}}\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 \u8218 \'82De urinis significantibus mortem\rquote }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 >\plain \f1\i\lang1033\fs22 I\plain \f1\lang1033\fs22 <\plain \f1\i\lang1033\fs22 ncipit de vrinis significantibus mortem\plain \f1\lang1033\fs22 . \plain \f1\i\lang1033\fs22 In omnibus istis infirmitatibus id est phisica \plain \f1\lang1033\fs22 [sonst: phtisica]\plain \f1\i\lang1033\fs22 , \plain \f1\lang1033\fs22 (118ra) \plain \f1\i\lang1033\fs22 ydropisi, appoplexia, ypilenisia\plain \f1\lang1033\fs22  \u8230 \'85 \plain \f1\i\lang1033\fs22 si vrina rubea fuerit morten significat. In frenetica, pleuretica, sinocha \u8230 \'85 si vrina rubea fuerint \plain \f1\lang1033\fs22 (!) \plain \f1\i\lang1033\fs22 an humida morten significat. \u8230 \'85\plain \f1\lang1033\fs22  - ... \plain \f1\i\lang1033\fs22 dolorem uidue et matricis que\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 febrem significat. Expliciunt vrine\plain \f1\lang1033\fs22 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Der Beginn \u252 \'fcbereinstimmend mit der Schlusspassage von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Isaac Iudaeus}}\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 \u8218 \'82Liber urinarum\rquote }}\plain \f1\lang1033\fs22 , vgl. Peine (Hg.), Die Harnschrift (s. o.), S. 75. Der Abschnitt aber auch separat \u252 \'fcberliefert, vgl. (ohne diese Hs.) eTK {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8334/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 0700K}}\plain \f1\lang1033\fs22 .}

