\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 IIr}}\plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24 Vorblatt II\plain \f1\lang1033\fs24 , Rectoseite): Inhaltsverzeichnis und Signatureintrag, s. o. Geschichte. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Au\u223 \'dferdem zahlreiche Nachtr\u228 \'e4ge (winzige Kursive, 14. Jh.): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Verse, Zitate, medizinische Notizen}}\plain \f1\b\lang1033\fs24  usw.\plain \f1\lang1033\fs24 , u. a.:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 - (li. Spalte) \plain \f1\i\lang1033\fs24 Lienteria \plain \f1\lang1033\fs24 [Magenruhr, Durchfall] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 est velox exitus cibi et potus}}\plain \f1\i\lang1033\fs24  ...\~\plain \f1\lang1033\fs24 ; \plain \f1\i\lang1033\fs24 Amor et odium remouent hominem \plain \f1\lang1033\fs24 [interlinear: \plain \f1\i\lang1033\fs24 aliter animam\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 a rectitudine iudicii ut agit Tholomeus in Centiloquio ...\plain \f1\lang1033\fs24 ;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 - (re. Spalte) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Urina est colamentum sangunis ex epate}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (Beginn von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theophilus}}\plain \f1\lang1033\fs24 : \u8218 \'82{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber urinarum}}\plain \f1\lang1033\fs24 \rquote ); \plain \f1\i\lang1033\fs24 Nota quod flebotomia est supefluitas sanguinea ...\plain \f1\lang1033\fs24 , zahlreiche weitere Eintr\u228 \'e4ge, meist eingeleitet durch \plain \f1\i\lang1033\fs24 Nota quod ...\plain \f1\lang1033\fs24 ; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 unten Verweis auf Rezept: \plain \f1\i\lang1033\fs24 Magister R. f. dixit, quod dedit cuidam ...\plain \f1\lang1033\fs24 ; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 unten vier salernitanische Verse: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Est triplex tipus}}\plain \f1\i\lang1033\fs24 : rigor, oripilatio, frigus. ...}

