\uc1
\pard\fi0\li0\qc\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Faszikel II (Bl. 46-76)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f2\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Beschreibstoff: \plain \f1\lang1033\fs22 Pergament. Haar- und Fleischseite deutlich unterschiedlich, Bl. 67-76 mit\plain \f1\b\lang1033\fs22  \plain \f1\lang1033\fs22 teils ausgepr\u228 \'e4gter Follikelstruktur\plain \f2\lang1033\fs22 .\plain \f1\lang1033\fs22\cf1  Etwas spr\u246 \'f6de. Gute Qualit\u228 \'e4t: recht gleichm\u228 \'e4\u223 \'dfige St\u228 \'e4rke, nur wenige L\u246 \'f6cher, Fehlstellen und N\u228 \'e4hte. \plain \f1\lang1033\fs22 Bl. 76 auf den beschriebenen Teil von 28,5 x 11-12 cm Gr\u246 \'f6\u223 \'dfe beschnitten.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Lagen: \plain \f1\lang1033\fs22 2IV\plain \f1\super\lang1033\fs24 61\plain \f1\lang1033\fs22 +(III-1)\plain \f1\super\lang1033\fs24 66\plain \f1\lang1033\fs22 +V\plain \f1\super\lang1033\fs24 76\plain \f1\lang1033\fs22\cf1 . Lagenz\u228 \'e4hlung \plain \f1\i\lang1033\fs22\cf1 I\plain \f1\lang1033\fs22\cf1  und \plain \f1\i\lang1033\fs22\cf1 II\plain \f1\lang1033\fs22\cf1  links unten auf der letzten Seite der Lage (53v und 61v, nicht jedoch 66v)\plain \f2\lang1033\fs22\cf1 .
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Schriftraum: \plain \f1\lang1033\fs22 26,5-27,5 x 15-15,5 cm. Zweispaltig. Eingerichtet mit Zeilenger\u252 \'fcst, doppelten Begrenzungslinien und zweispaltigem Interkolumnium. Durchgehend 75  Zeilen. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Schrift: \plain \f1\lang1033\fs22 Text von einer Hand (mit zw. Bl. 46-66 und 67-76 etwas schwankendem Duktus, aber sehr konstantem Formenrepertoire), s\u252 \'fcdlich beeinflusste {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Textualis}}\plain \f1\lang1033\fs22  auf gehobenem kalligraphischen Niveau, 3. Drittel 13. Jh., wohl S\u252 \'fcdfrankreich. \endash  Hinweisende, texterschlie\u223 \'dfende, gliedernde und korrigierende Marginalien von der Texthand selbst und mindestens f\u252 \'fcnf weiteren, zumeist  recht zeitnahen H\u228 \'e4nden, 3. Drittel 13. und 1. H\u228 \'e4lfte 14. Jh., auch Lesarten anderer Handschriften (\plain \f1\i\lang1033\fs22 in alio\plain \f1\lang1033\fs22  ..., z. B. 46v, 47v). Zeigeh\u228 \'e4nde.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\b\lang1033\fs22 Buchschmuck und Rubrizierung: {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Fleuronn\u233 \'e9-Initialen}}\plain \f1\lang1033\fs22  nur am Beginn der Texte 46ra, 58rb und 67ra. 46ra am Beginn der Sammlung neunzeilig, blau-rot gespaltener Buchstabenk\u246 \'f6rper mit gebogter und kopfstempelf\u246 \'f6rmiger Schaftaussparung, verziert mit Fleuronn\u233 \'e9 in der Gegenfarbe: in Besatz und Binnenraum Knospenb\u252 \'fcschel und -reihen, teils in Medaillons und Spiralen angeordnet, Knospen in der Gegenfarbe, Zwickelperlen und Fibrillen, Ablauf zu Fleuronn\u233 \'e9leiste mit abwechselnd roten gezahnten und blauen kopfstempelartigen Segmenten ausgestaltet, , Fadenausl\u228 \'e4ufer mit Fibrillen. 58rb dreizeilige blaue Lombarde, 67ra 17-zeilige rote Lombarde, beide mit gleichartigem Fleuronne in der Gegenfarbe in einfacherer Ausf\u252 \'fchrung (Knospenreihen, Spiralen, Fadenausl\u228 \'e4ufer, Fibrillen). \u220 \'dcberschriften in Rot, wohl nachgetragen (Textura, 1. H\u228 \'e4lfte 14. Jh., nordalpin). Sonst nicht rubriziert (Raum f\u252 \'fcr Alinea-Zeichen freigelassen, jedoch nicht ausgef\u252 \'fchrt).}

