\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 66ra-b}}\plain \f1\b\lang1033\fs22  \plain \f1\lang1033\fs22 (= Schum 68ra-b)\plain \f1\b\lang1033\fs22  Pesttraktat {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 \u8218 \'82Causa epidimiae et praeservatio eiusdem\lquote }}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat19 C<ausa epydimie et preseruacio eiusdem. Primo de epydimia}}\plain \f1\i\lang1033\fs22 , secundo de preseruacione eius et corrupcione aeris circumstantis dicendum est. Dicitur autem epydimia ab \u8222 \'84epy\ldblquote , quod est supra, et \u8222 \'84dimos\ldblquote , quod est continens uel aer\plain \f1\lang1033\fs22  ... \endash  ... (66rb) \plain \f1\i\lang1033\fs22 piperis, coriandri vel de omnibus vel de parte. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 eTK 0196E (nur diese Hs.). \endash  Abdruck aus dieser Hs. bei Sudhoff, Pestschriften 3 (1911), S. 41-46, S. 41f. zur hsl. \u220 \'dcberlieferung (3 Hss., darunter diese).}

