\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Z. B.: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Amplaustrum factum ex paritaria contrita cum eiusdem succo et olio camillarum calefactum}}\plain \f1\i\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Si pillule propter earum amaritudinem non possint a volenti eis vti\plain \f1\lang1033\fs22  \u8230 \'85; \plain \f1\i\lang1033\fs22 Nota mala complexio causans subtilitatem potest esse duplex\plain \f1\lang1033\fs22  \u8230 \'85; (36va) \plain \f1\i\lang1033\fs22 Nota mulier non potens concipere propter pinguedinem debet vti magno exercicio\plain \f1\lang1033\fs22  \u8230 \'85; \plain \f1\i\lang1033\fs22 Salvia cum vino sumpta post comestionem multum valet flecmaticis. \plain \f1\lang1033\fs22 (36vb) \plain \f1\i\lang1033\fs22 Nota fluxus sanguinis potest stringi multipliciter vel propter flebotomiam\plain \f1\lang1033\fs22  \u8230 \'85 . }

