\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 50v-54v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Notizen zu Avicenna \u8218 \'82Canon medicinae\lquote , Buch III, Fen 21, Tract. III-IV (Krankheiten, insb. Geschw\u252 \'fcre der Geb\u228 \'e4rmutter)}}\plain \f1\b\lang1033\fs22 :\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 Dicit Avicenna \plain \f1\lang1033\fs22 [Tract. III, Cap. 25?]\plain \f1\i\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 numerando egritudines contingentes matrice}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 (!)\plain \f1\i\lang1033\fs22  ex retentione\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 menstrvorum, quod retinet contingit suffocacio matricis ...\plain \f1\lang1033\fs22 ; (52v) \plain \f1\i\lang1033\fs22 Nota apostema\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 flecmaticum in matrice. Signa eius sunt ...\plain \f1\lang1033\fs22 ; (53r) \plain \f1\i\lang1033\fs22 Hic Auicenna comparat causas suffocacionis matricis\plain \f1\lang1033\fs22  ...; \plain \f1\i\lang1033\fs22 Cura suffocacionis matricis\plain \f1\lang1033\fs22  ...; (54r) [Tract. IV, Cap. 22:] \plain \f1\i\lang1033\fs22 \u8222 \'84Caro addita\ldblquote \plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 Nota in ore matricis ..., quando nascitur caro ...\plain \f1\lang1033\fs22 ; (54v) \plain \f1\i\lang1033\fs22 Dicit Auicenna, quod ventositas\plain \f1\lang1033\fs22  ... \plain \f1\i\lang1033\fs22 in matrice ... Reducat nos dominus letos ad continuandum studium et sanos. Fen 21\plain \f1\i\super\lang1033\fs24 a\plain \f2\lang1033\fs22 .\plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 Rest von 54v leer.}

