\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Regimen contra febrem pestilencie simplicem uel compositam cum malis apostematibus seu pustulis capitis}}\plain \f1\i\lang1033\fs22  \plain \f1\lang1033\fs22 ... \endash  \u8230 \'85 (143r) \plain \f1\i\lang1033\fs22 si fuerit carbunculus super eum pomum granatum coctum in aceto ponatur. Reliqua vero cyrurgicalia cyrurgicis derelinquo etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 Im Text 142v Erw\u228 \'e4hnung eines deutschen Pflanzennamen: \plain \f1\i\lang1033\fs22 herbam scabiosam maiorem pilosam, que knoyffwurcz vocatur\plain \f1\lang1033\fs22 . 
