\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 [es folgt Bl. 6-19 ein nach Wzzn. um 1390 erg\u228 \'e4nzter Papiersepternio:] 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f2\lang1033\fs22 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 6ra-8rb}}\plain \f1\b\lang1033\fs22  \plain \f1\lang1033\fs22 (Nachtrag von NH1)\plain \f1\b\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 Hippocrates}}\plain \f1\b\lang1033\fs22 : \u8218 \'82{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 Aphorismi}}\plain \f1\b\lang1033\fs22 \lquote , in der \u220 \'dcbersetzung des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat19 Constantinus Africanus}}\plain \f1\b\lang1033\fs22   (unvollst\u228 \'e4ndig, bis Particula IV, Aph. 54)
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs22 [\u220 \'dcberschrift, \u252 \'fcber dem Schriftraum:] \plain \f1\i\lang1033\fs22 Textus amphorismorum Ypocratis. Particula prima\plain \f1\lang1033\fs22  [Text:] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat19 >}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat19 U}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat19 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat19 ita brevis, ars longa}}\plain \f1\i\lang1033\fs22 , tempus autem acutum, experimentum vero fallax, iudicium difficile \u8230 \'85 \endash  \u8230 \'85 \plain \f1\lang1033\fs22 (8rb) [Part. IV, Aph. 54:] \plain \f1\i\lang1033\fs22 Quibus tusses sicce et modice prouocate in febribus urentibus non valde sitientes sunt. \plain \f1\lang1033\fs22 [Text bricht ab]
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 eTK 1704J. \endash  Ohne Prolog des Constantinus Africanus und Kommentar des Galenus. Verzeichnet als Addendum bei Kibre, Hippocrates Latinus (1985), S. XII (zu S. 55, III.A.4). \endash  Druck: GW 12477 (Florenz 1494), 12478 (N\u252 \'fcrnberg, nicht vor 1496) sowie mit den Articella-Drucken GW 2678-2683.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \par}

