\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 43ra-62ra}}\plain \f1\b\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Isaac Israelita}}\plain \f1\b\lang1033\fs24 : \u8218 \'82{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Liber urinarum}}\plain \f1\b\lang1033\fs24 \lquote  in der \u220 \'dcbersetzung des {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Constantinus Africanus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 43ra \u252 \'fcber der Spalte >\plain \f1\i\lang1033\fs24 Incipiunt vrine Ysac\plain \f1\lang1033\fs24 <
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 43ra Prolog (des Constantinis Africanus): {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >I<n latinis autem libris nunquam auctorem inuenire}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 [potui]\plain \f1\i\lang1033\fs24 , qui de urina certamque auctenticam cognicionem dederit ... Decima: De quaque vrina et ypostasi quid significet.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 43ra-62ra Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >V<rina est colamentum sanguinis et ceterorum similiter humorum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ... (62ra) \plain \f1\i\lang1033\fs24 vrina spumosa in superficie sicut uua dolorem significat renum. \plain \f1\lang1033\fs24 [Darunter:] \plain \f1\i\lang1033\fs24 Explicit Liber urinarum Ysaac. 
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs24 eTK 0688B-C (Prolog, Varianten), 1607L, 1608C (Text). \endash  Druck in: Opera omnia Ysaac, Lyon 1515 (mit Kommentar des Petrus Hispanus), Bl. 156rb-203rb. \endash  Edition: Peine, Die Harnschrift des Isaac Judaeus (1919), S. 10-75 (ohne diese Hs.). \endash  Abdruck des Textzeugen {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pavia, Bibliotheca universitaria, Cod. 449}}\plain \f1\lang1033\fs24 , mit Varianten aus {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Vatikan, BAV, Vat. lat. 2393}}\plain \f1\lang1033\fs24  und \u220 \'dcbersetzung ins Italienische: Fontana, Il libro delle urine di Isacco l'ebreo (1966) \endash  Zur hsl. \u220 \'dcberlieferung: Peine, ebd., S. 6-8 (35 Hss., darunter diese); Veit, Isaac Israeli: His Treatise on Urine (De Urinis) and its Reception in the Latin World (2015), S. 89-107 (54 vollst\u228 \'e4ndige Hss., darunter diese). }

