\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >I<n omnibus infirmitatibus hiis, scilicet thisis}}\plain \f1\i\lang1033\fs24 , ydrops, aboplexia, epilemsia \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24 , peripleumonia, paralisis, colica, disinetria, si urina rufa fuerit, mortem signat. ... \endash  ... \plain \f1\lang1033\fs24 (62rb) \plain \f1\i\lang1033\fs24 Si feminam \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  urinam habuerit quasi iumenti similem, dolor renum, uulue et matricis febrem signifcat.}

