\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Que conferunt capiti}}\plain \f1\i\lang1033\fs22 : Absinthium, abrotanum, accedula, actum, acorus\plain \f1\lang1033\fs22  ... \endash  ...  (98va) \plain \f1\i\lang1033\fs22 vinum moderate sumptum. Que nocent capiti \plain \f1\lang1033\fs22 ... - ... (101vb) \plain \f1\i\lang1033\fs22 genciana, galbanum, hermodactilli, herba yna et sic de aliis.\plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Anno m cccc xvii\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs22 <.
\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Krakau, Biblioteka Jagiello\u324 nska, Cod. 845, Bl. 7v-11v}}\plain \f1\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. 2113, S. 11-22}}\plain \f1\lang1033\fs22 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Breslau, Universit\u228 \'e4tsbibliothek, Cod. III. F. 20, Bl. 55r-57v}}\plain \f1\lang1033\fs22 . Vgl. Burchardt, ebd., S. 193. \endash  \u220 \'dcberschriften: \plain \f1\i\lang1033\fs22 Que oculis valent\plain \f1\lang1033\fs22  (98vb); \plain \f1\i\lang1033\fs22 Que nocent oculis\plain \f1\lang1033\fs22  (99ra); \plain \f1\i\lang1033\fs22 Que auribus valent\plain \f1\lang1033\fs22  (99ra); \plain \f1\i\lang1033\fs22 Que nocent auribus\plain \f1\lang1033\fs22  (99rb); \plain \f1\i\lang1033\fs22 Que naribus valent\plain \f1\lang1033\fs22  (99rb); [99va Raum freigelassen f\u252 \'fcr: \u8222 \'84Que ori et dentibus valent\ldblquote  o.\u228 \'e4.]; \plain \f1\i\lang1033\fs22 Que nocent dentibus\plain \f1\lang1033\fs22  (99vb); \plain \f1\i\lang1033\fs22 Que pectori valent\plain \f1\lang1033\fs22  (99vb); \plain \f1\i\lang1033\fs22 Que nocent pectori\plain \f1\lang1033\fs22  (100ra); \plain \f1\i\lang1033\fs22 Que conferunt pectori\plain \f1\lang1033\fs22  (100ra); \plain \f1\i\lang1033\fs22 Que conferunt cordi\plain \f1\lang1033\fs22  (100ra); \plain \f1\i\lang1033\fs22 Que cordi nocent\plain \f1\lang1033\fs22  (100rb); \plain \f1\i\lang1033\fs22 Que stomacho et intestinis valent\plain \f1\lang1033\fs22  (100rb); \plain \f1\i\lang1033\fs22 Que epati conferunt\plain \f1\lang1033\fs22  (100vb); \plain \f1\i\lang1033\fs22 Que nocent epati\plain \f1\lang1033\fs22  (101ra); \plain \f1\i\lang1033\fs22 Que spleni conferunt\plain \f1\lang1033\fs22  (101ra);\plain \f1\i\lang1033\fs22  Que nocent spleni \plain \f1\lang1033\fs22 (101rb); \plain \f1\i\lang1033\fs22 Que intestinis conferunt\plain \f1\lang1033\fs22  (101rb); \plain \f1\i\lang1033\fs22 Que viis vrinalibus et matrici conferunt\plain \f1\lang1033\fs22  (101rb); \plain \f1\i\lang1033\fs22 Que nocent matrici et neruis\plain \f1\lang1033\fs22  (101va); \plain \f1\i\lang1033\fs22 In causis generativorum valent\plain \f1\lang1033\fs22  (101ra); \plain \f1\i\lang1033\fs22 In causis neruorum valent\plain \f1\lang1033\fs22  (101va). \endash  Die Rubriken bieten meist eine Aufz\u228 \'e4hlung der entsprechenden Simplicia, bisweilen auch kurze Erl\u228 \'e4uterungen. Wahrscheinlich im Sinne eines Sachindex aus dem \u8218 \'82Aggregatum\lquote  oder Tabula 1 abgeleitet.}

