\par \pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f1\i\lang1033\fs22 Auri nobilitas luteam si vestiat ollam\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 Non ideo sequitur, hanc minus esse lutum\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Walther, Proverbia, Nr. 1795}}\plain \f1\lang1033\fs22 ). \plain \f1\i\lang1033\fs22 Verus amor miserum non dedignatur amicum\plain \f1\lang1033\fs22  (ebd. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Nr. 33204}}\plain \f1\lang1033\fs22 ); \plain \f1\i\lang1033\fs22 Nescio quid sit amor, nec amo, nec amor, nec amari\plain \f1\lang1033\fs22  / \plain \f1\i\lang1033\fs22 sed scio, si quis amat, vritur igne graui\plain \f1\lang1033\fs22  (ebd. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Nr. 16531}}\plain \f1\lang1033\fs22 ); \plain \f1\i\lang1033\fs22 Estque serena dies post longos gracior\plain \f1\lang1033\fs22  [imbres] / \plain \f1\i\lang1033\fs22 et post triste malum gratior ipsa salus\plain \f1\lang1033\fs22  (ebd. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Nr. 8061}}\plain \f1\lang1033\fs22 ).}
